#!/usr/bin/env node
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

export const SEMVER_RE = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z.-]+))?$/
const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/

const HEADER = `# Changelog

All notable changes to \`@ficsysfr/jsonforms_builder\` are documented here.
Format based on [Keep a Changelog](https://keepachangelog.com/),
versioning follows [SemVer](https://semver.org/).

<!-- Generated by \`scripts/build-changelog.mjs\`; edit \`changelog/X.Y.Z.md\`. -->
`

function parseScalar(raw) {
  const value = raw.trim()
  if (value === 'true') return true
  if (value === 'false') return false
  if (value === 'null' || value === '~' || value === '') return null
  if (
    (value.startsWith('"') && value.endsWith('"')) ||
    (value.startsWith("'") && value.endsWith("'"))
  ) {
    return value.slice(1, -1)
  }
  return value
}

export function compareSemver(leftVersion, rightVersion) {
  const left = SEMVER_RE.exec(leftVersion)
  const right = SEMVER_RE.exec(rightVersion)
  if (!left || !right) throw new Error('compareSemver expects valid SemVer values')

  for (let index = 1; index <= 3; index++) {
    const difference = Number(left[index]) - Number(right[index])
    if (difference !== 0) return difference < 0 ? -1 : 1
  }

  const leftPre = left[4]
  const rightPre = right[4]
  if (!leftPre && !rightPre) return 0
  if (!leftPre) return 1
  if (!rightPre) return -1

  const leftParts = leftPre.split('.')
  const rightParts = rightPre.split('.')
  for (let index = 0; index < Math.max(leftParts.length, rightParts.length); index++) {
    const leftPart = leftParts[index]
    const rightPart = rightParts[index]
    if (leftPart == null) return -1
    if (rightPart == null) return 1
    if (leftPart === rightPart) continue
    const leftNumeric = /^\d+$/.test(leftPart)
    const rightNumeric = /^\d+$/.test(rightPart)
    if (leftNumeric && rightNumeric) return Number(leftPart) < Number(rightPart) ? -1 : 1
    if (leftNumeric !== rightNumeric) return leftNumeric ? -1 : 1
    return leftPart < rightPart ? -1 : 1
  }
  return 0
}

export function parseEntry(raw, file = '<entry>') {
  const text = raw.replace(/\r\n/g, '\n')
  if (!text.startsWith('---\n')) {
    throw new Error(`${file}: missing frontmatter`)
  }

  const end = text.indexOf('\n---\n', 4)
  if (end === -1) throw new Error(`${file}: unclosed frontmatter`)

  const metadata = {}
  for (const line of text.slice(4, end).split('\n')) {
    const trimmed = line.trim()
    if (!trimmed || trimmed.startsWith('#')) continue
    const separator = trimmed.indexOf(':')
    if (separator === -1) throw new Error(`${file}: invalid frontmatter line "${trimmed}"`)
    metadata[trimmed.slice(0, separator).trim()] = parseScalar(trimmed.slice(separator + 1))
  }

  const body = text.slice(end + 5).trim()
  const version = String(metadata.version ?? '')
  const date = String(metadata.date ?? '')
  const title = String(metadata.title ?? '')
  const previous = metadata.previous ? String(metadata.previous) : ''

  if (!SEMVER_RE.test(version)) throw new Error(`${file}: invalid or missing SemVer version`)
  if (!ISO_DATE_RE.test(date)) throw new Error(`${file}: date must use YYYY-MM-DD`)
  if (new Date(`${date}T00:00:00Z`).toISOString().slice(0, 10) !== date) {
    throw new Error(`${file}: date is not a real calendar date`)
  }
  if (!title) throw new Error(`${file}: title is required`)
  if (!body) throw new Error(`${file}: body is empty`)
  if (previous && !SEMVER_RE.test(previous)) throw new Error(`${file}: previous must be SemVer`)
  if (previous && compareSemver(previous, version) >= 0) {
    throw new Error(`${file}: previous must be older than version`)
  }
  if (metadata.prerelease != null && typeof metadata.prerelease !== 'boolean') {
    throw new Error(`${file}: prerelease must be true or false`)
  }
  if ((metadata.prerelease === true) !== version.includes('-')) {
    throw new Error(`${file}: prerelease flag must match the version suffix`)
  }

  return {
    version,
    date,
    title,
    previous,
    prerelease: metadata.prerelease === true,
    body,
  }
}

export function readEntries(root = process.cwd()) {
  const sourceDirectory = join(root, 'changelog')
  if (!existsSync(sourceDirectory)) throw new Error(`${sourceDirectory}: directory not found`)

  const files = readdirSync(sourceDirectory)
    .filter((file) => file.endsWith('.md') && file !== 'README.md')
    .sort()

  if (files.length === 0) throw new Error(`${sourceDirectory}: no release entries found`)

  return files
    .map((file) => {
      const expectedVersion = file.slice(0, -3)
      const entry = parseEntry(
        readFileSync(join(sourceDirectory, file), 'utf8'),
        `changelog/${file}`,
      )
      if (entry.version !== expectedVersion) {
        throw new Error(`changelog/${file}: version must match the filename`)
      }
      return entry
    })
    .sort((left, right) => compareSemver(right.version, left.version))
}

function renderSection(entry, inferredPrevious = '') {
  const previous = entry.previous || inferredPrevious
  const label = previous
    ? `[${entry.version}](https://github.com/FicSysFR/jsonforms_builder/compare/${previous}...${entry.version})`
    : `[${entry.version}]`
  const warning = entry.prerelease
    ? '> ⚠️ Prerelease — published on npm under the `next` dist-tag.\n\n'
    : ''
  return `## ${label} - ${entry.date}\n\n${warning}${entry.body}\n`
}

export function renderChangelog(entries) {
  const sections = entries.map((entry, index) =>
    renderSection(entry, entries[index + 1]?.version ?? ''),
  )
  return `${HEADER}\n${sections.join('\n')}`
}

export function renderReleaseNotes(entries, version) {
  const index = entries.findIndex((entry) => entry.version === version)
  if (index === -1) throw new Error(`changelog/${version}.md: release entry not found`)
  const entry = entries[index]
  const warning = entry.prerelease
    ? '> ⚠️ Prerelease — published on npm under the `next` dist-tag.\n\n'
    : ''
  return `# ${entry.title}\n\n${warning}${entry.body}\n`
}

export function buildArtifacts(root = process.cwd()) {
  const entries = readEntries(root)
  return {
    entries,
    changelog: renderChangelog(entries),
  }
}

function writeIfChanged(path, content) {
  if (existsSync(path) && readFileSync(path, 'utf8') === content) return false
  mkdirSync(dirname(path), { recursive: true })
  writeFileSync(path, content, 'utf8')
  return true
}

function parseArgs(argv) {
  const options = { check: false, releaseNotes: '', out: '', root: process.cwd() }
  for (let index = 0; index < argv.length; index++) {
    const argument = argv[index]
    if (argument === '--check') options.check = true
    else if (argument === '--release-notes') options.releaseNotes = argv[++index] ?? ''
    else if (argument === '--out') options.out = argv[++index] ?? ''
    else if (argument === '--root') options.root = resolve(argv[++index] ?? process.cwd())
    else if (argument === '--help' || argument === '-h') {
      console.log(
        'Usage: node scripts/build-changelog.mjs [--check] [--root dir]\n' +
          '       node scripts/build-changelog.mjs --release-notes X.Y.Z [--out file]',
      )
      process.exit(0)
    } else throw new Error(`unknown argument: ${argument}`)
  }
  return options
}

function main() {
  const options = parseArgs(process.argv.slice(2))
  const { entries, changelog } = buildArtifacts(options.root)

  if (options.releaseNotes) {
    const notes = renderReleaseNotes(entries, options.releaseNotes)
    if (options.out) writeIfChanged(resolve(options.out), notes)
    else process.stdout.write(notes)
    return
  }

  const changelogPath = join(options.root, 'CHANGELOG.md')
  if (options.check) {
    if (!existsSync(changelogPath) || readFileSync(changelogPath, 'utf8') !== changelog) {
      throw new Error('CHANGELOG.md is not synchronized; run `yarn changelog:build`')
    }
    console.log(`Changelog is synchronized (${entries.length} releases).`)
    return
  }

  const changed = writeIfChanged(changelogPath, changelog)
  console.log(`${changed ? 'Generated' : 'Unchanged'} CHANGELOG.md (${entries.length} releases).`)
}

const invokedPath = process.argv[1] ? resolve(process.argv[1]) : ''
if (invokedPath === fileURLToPath(import.meta.url)) {
  try {
    main()
  } catch (error) {
    console.error(`ERROR: ${error.message}`)
    process.exit(1)
  }
}
